//! Differential testing of `ynab-core` against golden outputs generated by executing
//! the ORIGINAL Ember/SLIK classes (`SubcategoryCalculations` and `MonthlyCalculations`
//! sliced directly from `clone/public/assets/ynab_web/assets/wrapper-DkFKwf1z.js`) in Node.

use std::collections::{BTreeMap, HashMap};

use serde::Deserialize;

use crate::calc::goals_calc::{
    calculate_ember_goal_period, calculate_weekly_goal_target, evaluate_subcategory_goal, parse_ym,
    GoalEvaluationInput,
};
use crate::calc::monthly_calc::{calculate_monthly_timeline, MonthSummaryInput};
use crate::calc::subcategory_calc::{
    calculate_subcategories_for_month, CategoryMeta, SubcategoryMonthInput,
};

const GOLDEN_JSON: &str = include_str!("../../../../tools/golden/golden.json");

#[derive(Debug, Deserialize)]
struct GoldenFile {
    monthly: Vec<MonthlyCase>,
    subcategory: Vec<SubcategoryCase>,
    goals: Vec<GoalCase>,
    #[serde(rename = "goalPeriods")]
    goal_periods: Vec<GoalPeriodCase>,
    weekly: Vec<WeeklyCase>,
}

#[derive(Debug, Deserialize)]
struct MonthlyCase {
    id: String,
    input: Vec<MonthlyRowInput>,
    expected: Vec<MonthlyRowExpected>,
}

#[derive(Debug, Deserialize)]
